        jointDecision: joint,
        stdoutDigest: leaf.stdoutDigest,
        codexExitCode: leaf.exitCode,
        codexTimedOut: leaf.timedOut,
        managedRunId,
        managedReceiptId,
      };
      return wantsJson(args) ? result : formatResult(result);
    },
  };
